v=array(m.vertices,'co',3,np.float32);old=v.copy();li=array(m.loops,'vertex_index',1,np.int32);ix=array(m.polygons,'vertices',3,np.int32);uv0=array(m.uv_layers.active.data,'uv',2,np.float32);normal=array(m.corner_normals,'vector',3,np.float32);x=v[:,0].astype(np.float64);r=np.hypot(v[:,1].astype(np.float64),v[:,2]);theta=np.mod(np.arctan2(v[:,2].astype(np.float64),v[:,1]),math.tau);arc=theta*P['outside_radius_m_estimated'];safe=np.abs(x)<=.0410001;ids=np.flatnonzero(safe);expected=F.radius(x[ids])-F.depth(x[ids],arc[ids],False);crown=ids[np.abs(r[ids]-expected)<5e-7];a=F.fields(x[crown],arc[crown]);a1=F.fields(x[crown],arc[crown],True);overlap=(a>0).sum(axis=1)>=2;old_tails=np.any(a1!=a,axis=1);affected=overlap|old_tails;move=crown[affected];d0=F.depth(x[move],arc[move],False);d1=F.depth(x[move],arc[move],True);extra=d1-d0;bound=P['groove_depth_m_estimated']*(3**(1/P['junction_union_p'])-1);assert extra.min()>=-P['groove_depth_m_estimated']-1e-15 and extra.max()<=bound+1e-15
