h=2e-6;xx=x[crown];ar=arc[crown];rr=F.crown(xx,ar);rx=(F.crown(xx+h,ar)-F.crown(xx-h,ar))/(2*h);rs=(F.crown(xx,ar+h)-F.crown(xx,ar-h))/(2*h);co=np.cos(theta[crown]);si=np.sin(theta[crown]);ps=np.stack([np.zeros_like(rs),rs*co-rr/P['outside_radius_m_estimated']*si,rs*si+rr/P['outside_radius_m_estimated']*co],axis=-1);px=np.stack([np.ones_like(rx),rx*co,rx*si],axis=-1);nn=np.cross(ps,px);nn/=np.linalg.norm(nn,axis=1)[:,None];mapn=np.full(len(v),-1,np.int32);mapn[crown]=np.arange(len(crown));lc=mapn[li]>=0;normal[lc]=nn[mapn[li[lc]]];m.normals_split_custom_set(normal);m.update();assert np.array_equal(uv0,array(m.uv_layers.active.data,'uv',2,np.float32));assert np.array_equal(ix,array(m.polygons,'vertices',3,np.int32));m.calc_loop_triangles();tri=v[ix].astype(np.float64);areas=np.linalg.norm(np.cross(tri[:,1]-tri[:,0],tri[:,2]-tri[:,0]),axis=1)/2;vol=float(np.einsum('ij,ij->i',tri[:,0],np.cross(tri[:,1],tri[:,2])).sum()/6);assert areas.min()>1e-18
